#include <iostream>
#include <stdexcept>
using namespace std;

int divide(int a, int b) {
    if (b == 0) {
        throw runtime_error("除数不能是 0 喵");
    }
    return a / b;
}

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    try {
        int result = divide(a, b);
        cout << "答案是 " << result << " 喵" << endl;
    } catch (const runtime_error& e) {
        cout << "接住了：" << e.what() << endl;
    }
    return 0;
}
